<?php include 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']=='POST'){ $name=trim($_POST['name']); $email=trim($_POST['email']); $fb=trim($_POST['message']); if($name==''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($fb)<20){$msg='Enter valid email and feedback of at least 20 characters';} else {$stmt=mysqli_prepare($conn,'INSERT INTO feedback(name,email,message) VALUES(?,?,?)'); mysqli_stmt_bind_param($stmt,'sss',$name,$email,$fb); mysqli_stmt_execute($stmt);}}
$page=max(1,(int)($_GET['page']??1)); $limit=5; $offset=($page-1)*$limit; $res=mysqli_query($conn,"SELECT * FROM feedback ORDER BY id DESC LIMIT $limit OFFSET $offset"); ?>
<!DOCTYPE html><html><head><title>Q16 Feedback</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h1>Online Feedback Form</h1><form method="post"><input name="name" placeholder="Name"><input name="email" placeholder="Email"><textarea name="message" placeholder="Feedback message"></textarea><button>Submit</button></form><p class="error"><?php echo $msg; ?></p><table><tr><th>Name</th><th>Email</th><th>Feedback</th></tr><?php while($r=mysqli_fetch_assoc($res)){ ?><tr><td><?php echo $r['name']; ?></td><td><?php echo $r['email']; ?></td><td><?php echo $r['message']; ?></td></tr><?php } ?></table><a href="?page=<?php echo max(1,$page-1); ?>">Previous</a> | <a href="?page=<?php echo $page+1; ?>">Next</a></div><script src="script.js"></script></body></html>
